<style>
.rda-map-wrap{font-family:Geist,sans-serif;color:#12203A}
.rda-map-head{margin-bottom:20px}
.rda-eyebrow{display:flex;align-items:center;gap:10px;font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:#9a6a15;margin-bottom:8px}
.rda-eyebrow::before{content:"";width:22px;height:2px;background:#C9A227;border-radius:2px}
.rda-map-head h2{font-size:clamp(24px,3.2vw,34px);font-weight:800;letter-spacing:-.02em;line-height:1.12;margin:0 0 8px}
.rda-map-head p{margin:0;color:#5A6878;font-size:15.5px;line-height:1.6;max-width:70ch}

.rda-map-grid{display:grid;grid-template-columns:380px 1fr;gap:18px;align-items:start}
.rda-side{display:flex;flex-direction:column;gap:14px}

.rda-filters{background:#fff;border:1px solid #E4E9EF;border-radius:16px;padding:18px}
.rda-filters h3{margin:0 0 14px;font-size:15px;font-weight:800;letter-spacing:-.01em}
.rda-frow{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.rda-field{display:flex;flex-direction:column;gap:6px;min-width:0}
.rda-field.full{grid-column:1/-1}
.rda-field label{font-size:10.5px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#5A6878}
.rda-field select,.rda-field input{
  font:inherit;font-size:14.5px;padding:11px 12px;border:1px solid #E4E9EF;border-radius:12px;
  background:#F5F7FA;color:#12203A;width:100%;
}
.rda-field select:focus,.rda-field input:focus{outline:none;border-color:#C9A227;background:#fff;box-shadow:0 0 0 3px rgba(201,162,39,.18)}
.rda-chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}
.rda-chip{border:1px solid #E4E9EF;background:#F5F7FA;color:#12203A;border-radius:999px;padding:7px 13px;font-size:12.5px;font-weight:600;cursor:pointer}
.rda-chip[aria-pressed="true"]{background:#0E1F3C;border-color:#0E1F3C;color:#fff}
.rda-count{font-size:13px;color:#5A6878;margin-top:12px;padding-top:12px;border-top:1px solid #E4E9EF}
.rda-count b{color:#12203A}

.rda-list{display:flex;flex-direction:column;gap:12px;max-height:640px;overflow-y:auto;padding-right:4px}
.rda-item{
  display:grid;grid-template-columns:96px 1fr;gap:12px;background:#fff;border:1px solid #E4E9EF;
  border-radius:14px;padding:12px;cursor:pointer;transition:border-color .14s ease,box-shadow .14s ease;
}
.rda-item:hover,.rda-item.is-active{border-color:#C9A227;box-shadow:0 8px 24px rgba(10,24,48,.10)}
.rda-thumb{width:96px;height:80px;border-radius:10px;background:linear-gradient(160deg,#EDF2F9,#DFE6F0);object-fit:cover}
.rda-item .tp{font-size:10.5px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#5A6878}
.rda-item .tt{font-size:14.5px;font-weight:700;line-height:1.25;margin:3px 0 3px}
.rda-item .ad{font-size:12.5px;color:#5A6878;line-height:1.4}
.rda-item .pr{display:flex;align-items:baseline;gap:8px;margin-top:6px;flex-wrap:wrap}
.rda-item .pr s{font-size:12px;color:#8A97A6}
.rda-item .pr b{font-size:16px;font-weight:800;letter-spacing:-.02em}
.rda-badge{font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:4px 8px;border-radius:6px;background:#0E7C56;color:#fff}
.rda-empty{background:#fff;border:1px dashed #D8DFE9;border-radius:14px;padding:26px;text-align:center;color:#5A6878;font-size:14.5px}

.rda-map{
  height:min(72vh,700px);border-radius:18px;overflow:hidden;border:1px solid #E4E9EF;
  background:#EDF2F9;position:sticky;top:96px;
}
.rda-map-fallback{display:flex;align-items:center;justify-content:center;height:100%;padding:26px;text-align:center;color:#5A6878;font-size:14.5px;line-height:1.6}
.leaflet-popup-content-wrapper{border-radius:14px}
.leaflet-popup-content{margin:12px 14px;font-family:Geist,sans-serif}
.rda-pop .tp{font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#5A6878}
.rda-pop .tt{font-size:15px;font-weight:800;margin:3px 0 2px;color:#12203A}
.rda-pop .ad{font-size:12.5px;color:#5A6878;line-height:1.4}
.rda-pop .pr{margin-top:7px}
.rda-pop .pr s{font-size:11.5px;color:#8A97A6;display:block}
.rda-pop .pr b{font-size:17px;font-weight:800;color:#12203A;letter-spacing:-.02em}
.rda-pop a{display:inline-block;margin-top:10px;background:#C9A227;color:#1B1403;font-weight:700;font-size:13px;
  padding:9px 16px;border-radius:999px;text-decoration:none}

@media (max-width:980px){
  .rda-map-grid{grid-template-columns:1fr}
  .rda-map{position:static;height:340px;order:-1}
  .rda-list{max-height:none}
}
</style>

<div class="rda-map-wrap">
  <div class="rda-map-head">
    <div class="rda-eyebrow">Mapa de leilão</div>
    <h2>Veja onde estão os imóveis antes de escolher</h2>
    <p>Endereço no mapa, avaliação, lance e desconto lado a lado. Clique no pino para abrir o imóvel — e peça a pré-análise antes de dar qualquer lance.</p>
  </div>

  <div class="rda-map-grid">
    <div class="rda-side">
      <div class="rda-filters">
        <h3>Filtrar</h3>
        <div class="rda-frow">
          <div class="rda-field">
            <label for="m-uf">Estado</label>
            <select id="m-uf"><option value="">Todos</option></select>
          </div>
          <div class="rda-field">
            <label for="m-cidade">Cidade</label>
            <select id="m-cidade"><option value="">Todas</option></select>
          </div>
          <div class="rda-field">
            <label for="m-tipo">Tipo</label>
            <select id="m-tipo"><option value="">Todos</option></select>
          </div>
          <div class="rda-field">
            <label for="m-max">Lance até (R$)</label>
            <input id="m-max" type="number" step="10000" placeholder="Sem limite">
          </div>
        </div>
        <div class="rda-chips">
          <button class="rda-chip" id="m-fgts" aria-pressed="false" type="button">Aceita FGTS</button>
          <button class="rda-chip" id="m-fin" aria-pressed="false" type="button">Aceita financiamento</button>
          <button class="rda-chip" id="m-desoc" aria-pressed="false" type="button">Desocupado</button>
          <button class="rda-chip" id="m-off" aria-pressed="false" type="button">Desconto acima de 50%</button>
        </div>
        <div class="rda-count"><b id="m-count">0</b> imóveis no mapa</div>
      </div>

      <div class="rda-list" id="m-list"></div>
    </div>

    <div class="rda-map" id="m-map">
      <div class="rda-map-fallback" id="m-fallback">Carregando o mapa…</div>
    </div>
  </div>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"></script>
<script>
(function(){
  /* ================== CONFIG ==================
     WHATSAPP  — número para a pré-análise
     CENTRO    — onde o mapa abre (Rio de Janeiro)
     IMOVEIS   — a lista. Preencha aqui, ou deixe que o script leia
                 window.SienaImoveis / window.REI_IMOVEIS do seu portal.
     Campos: {id,tipo,titulo,endereco,cidade,uf,lat,lng,avaliacao,lance,
              desconto,fgts,financia,desocupado,foto,url}
     ============================================ */
  var WHATSAPP = '5521977470996';
  var CENTRO   = [-22.9068, -43.1729];
  var ZOOM     = 10;

  var IMOVEIS = [
    {id:'1', tipo:'Casa', titulo:'Jardim Catarina', endereco:'Rua Gonçalo Sampaio, 31 — casa 07', cidade:'São Gonçalo', uf:'RJ', lat:-22.8236, lng:-43.0530, avaliacao:142000, lance:14200, desconto:90, fgts:false, financia:false, desocupado:false, foto:'', url:'#'},
    {id:'2', tipo:'Casa', titulo:'Santa Catarina', endereco:'Travessa Batista, 607 — casa 02', cidade:'São Gonçalo', uf:'RJ', lat:-22.8402, lng:-43.0611, avaliacao:161684, lance:16168, desconto:90, fgts:true, financia:false, desocupado:false, foto:'', url:'#'},
    {id:'3', tipo:'Casa', titulo:'Madureira', endereco:'Rua Delfina Alves, 614 — lote 206', cidade:'Rio de Janeiro', uf:'RJ', lat:-22.8735, lng:-43.3382, avaliacao:184000, lance:18400, desconto:90, fgts:true, financia:true, desocupado:true, foto:'', url:'#'},
    {id:'4', tipo:'Apartamento', titulo:'Olaria', endereco:'Rua Itamirim, 12 — apto. 201', cidade:'Rio de Janeiro', uf:'RJ', lat:-22.8447, lng:-43.2660, avaliacao:151000, lance:15100, desconto:90, fgts:false, financia:true, desocupado:false, foto:'', url:'#'},
    {id:'5', tipo:'Casa', titulo:'Vila Centenário', endereco:'Rua Leopoldina Tomé, 357', cidade:'Duque de Caxias', uf:'RJ', lat:-22.7858, lng:-43.3113, avaliacao:370000, lance:45727, desconto:88, fgts:true, financia:true, desocupado:false, foto:'', url:'#'},
    {id:'6', tipo:'Apartamento', titulo:'Catumbi', endereco:'Rua Eliseu Visconti, 120 — apto. 102', cidade:'Rio de Janeiro', uf:'RJ', lat:-22.9155, lng:-43.1953, avaliacao:240000, lance:29308, desconto:88, fgts:false, financia:false, desocupado:true, foto:'', url:'#'}
  ];

  /* Se o portal já expõe os imóveis, usa os de verdade */
  if (window.REI_IMOVEIS && window.REI_IMOVEIS.length) IMOVEIS = window.REI_IMOVEIS;
  else if (window.SienaImoveis && typeof window.SienaImoveis.lista === 'function') {
    try { var l = window.SienaImoveis.lista(); if (l && l.length) IMOVEIS = l; } catch(e){}
  }

  /* ================== HELPERS ================== */
  function brl(n){ n = Number(n)||0; return n.toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}); }
  function uniq(arr){ return arr.filter(function(v,i,s){ return v && s.indexOf(v)===i; }).sort(); }
  function fill(sel, vals){
    var el = document.getElementById(sel); if(!el) return;
    vals.forEach(function(v){ var o=document.createElement('option'); o.value=v; o.textContent=v; el.appendChild(o); });
  }

  fill('m-uf', uniq(IMOVEIS.map(function(i){return i.uf;})));
  fill('m-cidade', uniq(IMOVEIS.map(function(i){return i.cidade;})));
  fill('m-tipo', uniq(IMOVEIS.map(function(i){return i.tipo;})));

  /* ================== MAPA ================== */
  var map = null, layer = null, marcadores = {};
  var elMap = document.getElementById('m-map');
  var elFb  = document.getElementById('m-fallback');

  if (window.L && elMap) {
    elFb.remove();
    map = L.map('m-map', {scrollWheelZoom:false}).setView(CENTRO, ZOOM);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '&copy; OpenStreetMap'
    }).addTo(map);
    layer = L.layerGroup().addTo(map);
    map.on('click', function(){ map.scrollWheelZoom.enable(); });
  } else if (elFb) {
    elFb.textContent = 'O mapa não pôde ser carregado agora. A lista de imóveis ao lado continua funcionando normalmente.';
  }

  function pino(cor){
    return L.divIcon({
      className:'',
      html:'<div style="width:30px;height:30px;border-radius:50% 50% 50% 0;transform:rotate(-45deg);background:'+cor+';border:2px solid #fff;box-shadow:0 4px 10px rgba(10,24,48,.35)"></div>',
      iconSize:[30,30], iconAnchor:[15,28], popupAnchor:[0,-26]
    });
  }

  /* ================== FILTRO E RENDER ================== */
  function filtrados(){
    var uf = document.getElementById('m-uf').value;
    var cid = document.getElementById('m-cidade').value;
    var tipo = document.getElementById('m-tipo').value;
    var max = parseFloat(document.getElementById('m-max').value) || Infinity;
    var fgts = document.getElementById('m-fgts').getAttribute('aria-pressed')==='true';
    var fin  = document.getElementById('m-fin').getAttribute('aria-pressed')==='true';
    var des  = document.getElementById('m-desoc').getAttribute('aria-pressed')==='true';
    var off  = document.getElementById('m-off').getAttribute('aria-pressed')==='true';

    return IMOVEIS.filter(function(i){
      if (uf && i.uf !== uf) return false;
      if (cid && i.cidade !== cid) return false;
      if (tipo && i.tipo !== tipo) return false;
      if (Number(i.lance) > max) return false;
      if (fgts && !i.fgts) return false;
      if (fin && !i.financia) return false;
      if (des && !i.desocupado) return false;
      if (off && Number(i.desconto) < 50) return false;
      return true;
    });
  }

  function popupHtml(i){
    var msg = encodeURIComponent('Quero a pré-análise do imóvel: ' + i.titulo + ' — ' + i.endereco + ' (' + i.cidade + '/' + i.uf + ')');
    return '<div class="rda-pop">' +
      '<div class="tp">' + i.tipo + ' · ' + i.cidade + '/' + i.uf + '</div>' +
      '<div class="tt">' + i.titulo + '</div>' +
      '<div class="ad">' + i.endereco + '</div>' +
      '<div class="pr"><s>Avaliação ' + brl(i.avaliacao) + '</s><b>' + brl(i.lance) + '</b></div>' +
      '<a href="https://wa.me/' + WHATSAPP + '?text=' + msg + '" target="_blank" rel="noopener">Receber pré-análise</a>' +
      '</div>';
  }

  function itemHtml(i){
    return '<article class="rda-item" data-id="' + i.id + '">' +
      (i.foto ? '<img class="rda-thumb" src="' + i.foto + '" alt="">' : '<div class="rda-thumb"></div>') +
      '<div>' +
        '<div class="tp">' + i.tipo + ' · ' + i.cidade + '/' + i.uf + '</div>' +
        '<div class="tt">' + i.titulo + '</div>' +
        '<div class="ad">' + i.endereco + '</div>' +
        '<div class="pr"><s>' + brl(i.avaliacao) + '</s><b>' + brl(i.lance) + '</b>' +
          (i.desconto ? '<span class="rda-badge">' + i.desconto + '% off</span>' : '') +
        '</div>' +
      '</div>' +
    '</article>';
  }

  function render(){
    var lista = filtrados();
    document.getElementById('m-count').textContent = lista.length;

    var el = document.getElementById('m-list');
    el.innerHTML = lista.length ? lista.map(itemHtml).join('')
      : '<div class="rda-empty">Nenhum imóvel com esses filtros. Tente ampliar a cidade ou a faixa de lance.</div>';

    if (map && layer) {
      layer.clearLayers(); marcadores = {};
      var pts = [];
      lista.forEach(function(i){
        if (typeof i.lat !== 'number' || typeof i.lng !== 'number') return;
        var cor = Number(i.desconto) >= 50 ? '#0E7C56' : '#C9A227';
        var m = L.marker([i.lat, i.lng], {icon: pino(cor)}).addTo(layer).bindPopup(popupHtml(i));
        marcadores[i.id] = m;
        pts.push([i.lat, i.lng]);
      });
      if (pts.length) map.fitBounds(pts, {padding:[40,40], maxZoom:13});
    }

    el.querySelectorAll('.rda-item').forEach(function(card){
      card.addEventListener('click', function(){
        el.querySelectorAll('.rda-item').forEach(function(c){ c.classList.remove('is-active'); });
        card.classList.add('is-active');
        var m = marcadores[card.getAttribute('data-id')];
        if (m && map){ map.setView(m.getLatLng(), 15, {animate:true}); m.openPopup(); }
        if (window.dataLayer) window.dataLayer.push({event:'mapa_imovel_clique', imovel:card.querySelector('.tt').textContent});
      });
    });
  }

  ['m-uf','m-cidade','m-tipo','m-max'].forEach(function(id){
    var e = document.getElementById(id); if (e) e.addEventListener('input', render);
  });
  ['m-fgts','m-fin','m-desoc','m-off'].forEach(function(id){
    var e = document.getElementById(id); if (!e) return;
    e.addEventListener('click', function(){
      e.setAttribute('aria-pressed', e.getAttribute('aria-pressed')==='true' ? 'false' : 'true');
      render();
    });
  });

  render();
})();
</script>
  </div>
</section>

