        <ul class="calc-lines">
          <li><span>Lance</span><b id="o-lance">—</b></li>
          <li><span>Custos de aquisição</span><b id="o-aquis">—</b></li>
          <li><span>Débitos do imóvel</span><b id="o-debitos">—</b></li>
