<script>
(function(){
  var body = document.body;
  var WA = '5521977470996';

  /* ============================================================
     LOGO DO REI DO APÊ
     Cole aqui o endereço da sua logo (ou um data:image/... )
     Ex.: var LOGO = 'https://reidoape.com.br/img/logo.png';
     Enquanto estiver vazio, o site usa a marca desenhada em SVG.
     ============================================================ */
  var LOGO = '';

  if (LOGO) {
    document.querySelectorAll('.brand').forEach(function(a){
      var img = document.createElement('img');
      img.className = 'brand-img';
      img.src = LOGO;
      img.alt = 'Rei do Apê';
      img.onload = function(){
        var svg = a.querySelector('.brand-mark');
        var nm  = a.querySelector('.brand-name');
        if (svg) svg.remove();
        if (nm) nm.remove();
      };
      img.onerror = function(){ img.remove(); };
      a.insertBefore(img, a.firstChild);
    });
  }


  /* ---------- MENU ---------- */
  var burger = document.getElementById('burger');
  var closenav = document.getElementById('closenav');
  var scrim = document.getElementById('scrim');
  var items = Array.prototype.slice.call(document.querySelectorAll('.nav-item[data-menu]'));
  function isMobile(){ return window.matchMedia('(max-width:1024px)').matches; }
  function closeAll(){
    items.forEach(function(it){
      it.classList.remove('open');
      var b = it.querySelector('.nav-link');
      if (b && b.tagName === 'BUTTON') b.setAttribute('aria-expanded','false');
    });
  }
  function openDrawer(open){
    body.classList.toggle('menu-open', open);
    if (burger) burger.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (!open) closeAll();
  }
  if (burger) burger.addEventListener('click', function(){ openDrawer(!body.classList.contains('menu-open')); });
  if (closenav) closenav.addEventListener('click', function(){ openDrawer(false); });
  if (scrim) scrim.addEventListener('click', function(){ openDrawer(false); });
  items.forEach(function(it){
    var btn = it.querySelector('.nav-link');
    if (!btn || btn.tagName !== 'BUTTON') return;
    btn.addEventListener('click', function(e){
      e.preventDefault();
      var willOpen = !it.classList.contains('open');
      if (!isMobile()) closeAll();
      else items.forEach(function(o){ if (o !== it){ o.classList.remove('open'); var ob=o.querySelector('.nav-link'); if(ob&&ob.tagName==='BUTTON') ob.setAttribute('aria-expanded','false'); } });
      it.classList.toggle('open', willOpen);
      btn.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
    });
  });
  document.addEventListener('click', function(e){ if (isMobile()) return; if (!e.target.closest('.nav-item')) closeAll(); });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape'){ closeAll(); openDrawer(false); } });
  document.querySelectorAll('.nav a[href^="#"]').forEach(function(a){ a.addEventListener('click', function(){ openDrawer(false); }); });
  window.addEventListener('resize', function(){ if (!isMobile() && body.classList.contains('menu-open')) openDrawer(false); });

  /* ---------- ABAS E CHIPS DA BUSCA ---------- */
  var tabs = Array.prototype.slice.call(document.querySelectorAll('.tabs .tab'));
  tabs.forEach(function(t){
    t.addEventListener('click', function(){
      tabs.forEach(function(o){ o.setAttribute('aria-selected','false'); });
      t.setAttribute('aria-selected','true');
      window.dataLayer.push({event:'busca_aba', aba:t.textContent.trim()});
    });
  });
  Array.prototype.slice.call(document.querySelectorAll('.search-foot .chip')).forEach(function(c){
    c.addEventListener('click', function(){
      c.setAttribute('aria-pressed', c.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
    });
  });

  /* ---------- ATALHOS ---------- */
  document.querySelectorAll('[data-jump]').forEach(function(el){
    el.addEventListener('click', function(){
      var t = document.querySelector(el.getAttribute('data-jump'));
      if (t) t.scrollIntoView({behavior:'smooth', block:'start'});
    });
  });

  /* ---------- FILTRO DE SERVIÇOS ---------- */
  var cards = Array.prototype.slice.call(document.querySelectorAll('#svc-grid .svc'));
  function aplicarFiltro(f){
    cards.forEach(function(c){
      var ok = (f === 'todos') || c.getAttribute('data-cat') === f;
      c.style.display = ok ? '' : 'none';
    });
    document.querySelectorAll('#filters .f-btn').forEach(function(b){
      b.classList.toggle('on', b.getAttribute('data-f') === f);
    });
  }
  document.querySelectorAll('#filters .f-btn').forEach(function(b){
    b.addEventListener('click', function(){ aplicarFiltro(b.getAttribute('data-f')); });
  });

  /* ---------- MODAL SAIBA MAIS ---------- */
  var ov = document.getElementById('ov');
  var mvIc = document.getElementById('mv-ic');
  var mvTag = document.getElementById('mv-tag');
  var mvTit = document.getElementById('mv-title');
  var mvBody = document.getElementById('mv-body');
  var mvCta = document.getElementById('mv-cta');
  var lastFocus = null;

  function abrirModal(card){
    lastFocus = document.activeElement;
    var titulo = card.querySelector('h3').textContent.trim();
    var tag = card.querySelector('.tagline');
    mvIc.innerHTML = card.querySelector('.svc-ic').innerHTML;
    mvTag.textContent = tag ? tag.textContent : '';
    mvTit.textContent = titulo;
    mvBody.innerHTML = card.querySelector('.svc-detail').innerHTML;
    mvCta.href = 'https://wa.me/' + WA + '?text=' + encodeURIComponent('Olá! Quero saber mais sobre: ' + titulo);
    ov.classList.add('on');
    body.style.overflow = 'hidden';
    document.getElementById('mv-close').focus();
    window.dataLayer.push({event:'servico_saiba_mais', servico:titulo});
  }
  function fecharModal(){
    ov.classList.remove('on');
    body.style.overflow = '';
    if (lastFocus) lastFocus.focus();
  }
  document.querySelectorAll('[data-open]').forEach(function(b){
    b.addEventListener('click', function(){ abrirModal(b.closest('.svc')); });
  });
  document.getElementById('mv-close').addEventListener('click', fecharModal);
  document.getElementById('mv-more').addEventListener('click', fecharModal);
  ov.addEventListener('click', function(e){ if (e.target === ov) fecharModal(); });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape' && ov.classList.contains('on')) fecharModal(); });

  /* ---------- ACCORDION DE REGRAS ---------- */
  document.querySelectorAll('.acc > button').forEach(function(b){
    b.addEventListener('click', function(){
      var acc = b.parentElement;
      var abrindo = !acc.classList.contains('on');
      acc.classList.toggle('on');
      if (abrindo) window.dataLayer.push({event:'regra_aberta', regra:b.querySelector('.t').textContent.trim()});
    });
  });

  /* ---------- CALCULADORA DE VIABILIDADE ---------- */
  var CIDS = ['c-arremat','c-mercado','c-leiloeiro','c-itbi','c-registro','c-condo','c-iptu','c-conc','c-desoc','c-juri','c-reforma','c-corretagem','c-ir','c-entrada','c-taxa','c-prazo'];
  function v(id){ var e = document.getElementById(id); return e ? (parseFloat(e.value) || 0) : 0; }
  function brl(n){
    if (!isFinite(n)) n = 0;
    return n.toLocaleString('pt-BR', {style:'currency', currency:'BRL', maximumFractionDigits:0});
  }
  function calcular(){
    var lance = v('c-arremat');
    var mercado = v('c-mercado');

    var aquis = lance * (v('c-leiloeiro') + v('c-itbi') + v('c-registro')) / 100;
    var debitos = v('c-condo') + v('c-iptu') + v('c-conc');
    var desoc = v('c-desoc') + v('c-juri');
    var reforma = v('c-reforma');

    var corretagem = mercado * v('c-corretagem') / 100;
    var custoBase = lance + aquis + debitos + desoc + reforma;
    var ganho = Math.max(0, mercado - corretagem - custoBase);
    var ir = ganho * v('c-ir') / 100;
    var revenda = corretagem + ir;

    var total = custoBase + revenda;
    var lucro = mercado - total;

    /* financiado */
    var entrada = lance * v('c-entrada') / 100;
    var financiado = lance - entrada;
    var i = v('c-taxa') / 100 / 12;
    var n = v('c-prazo');
    var parcela = (i > 0 && n > 0) ? (financiado * i) / (1 - Math.pow(1 + i, -n)) : (n > 0 ? financiado / n : 0);

    document.getElementById('o-lance').textContent = brl(lance);
    document.getElementById('o-aquis').textContent = brl(aquis);
    document.getElementById('o-debitos').textContent = brl(debitos);
    document.getElementById('o-desoc').textContent = brl(desoc);
    document.getElementById('o-reforma').textContent = brl(reforma);
    document.getElementById('o-revenda').textContent = brl(revenda);
    document.getElementById('o-total').textContent = brl(total);
    document.getElementById('o-lucro').textContent = brl(lucro);
    document.getElementById('o-avista').textContent = brl(total);
    document.getElementById('o-fin').textContent = brl(entrada + aquis + debitos + desoc + reforma) + ' + ' + brl(parcela) + '/mês';

    var margem = mercado > 0 ? (lucro / mercado) * 100 : 0;
    var box = document.getElementById('o-verdict');
    box.classList.remove('ok','bad');
    if (mercado <= 0 || lance <= 0) {
      box.textContent = 'Preencha o valor do lance e o valor de mercado.';
    } else if (lucro <= 0) {
      box.classList.add('bad');
      box.innerHTML = '<b>Atenção.</b> Somando tudo, o custo total passa do valor de mercado. Nesse cenário o negócio não fecha — reveja o lance, os débitos ou o custo de desocupação.';
    } else if (margem < 15) {
      box.innerHTML = '<b>Margem apertada:</b> ' + margem.toFixed(1) + '%. Dá lucro, mas qualquer surpresa de obra ou de desocupação come o resultado. Vale uma diligência antes.';
    } else {
      box.classList.add('ok');
      box.innerHTML = '<b>Margem de ' + margem.toFixed(1) + '%</b> sobre o valor de mercado. Confirme os débitos e a ocupação com uma diligência antes de dar o lance.';
    }
  }
  CIDS.forEach(function(id){
    var e = document.getElementById(id);
    if (e) e.addEventListener('input', calcular);
  });
  if (document.getElementById('c-arremat')) calcular();

  /* ---------- FORMULÁRIO DE INDICAÇÃO ---------- */
  var frm = document.getElementById('frm');
  if (frm) {
    frm.addEventListener('submit', function(e){
      e.preventDefault();
      var d = {};
      new FormData(frm).forEach(function(val, key){ d[key] = val; });
      var msg = '*NOVA INDICAÇÃO — Indique e Ganhe*%0A%0A' +
        '*Quem indicou:* ' + (d.nome||'') + '%0A' +
        '*WhatsApp:* ' + (d.fone||'') + '%0A' +
        (d.pix ? '*Chave Pix:* ' + d.pix + '%0A' : '') +
        '%0A*Tipo:* ' + (d.tipo||'') + '%0A' +
        '*Indicado:* ' + (d.indicado||'') + '%0A' +
        '*WhatsApp do indicado:* ' + (d.indicadoFone||'') + '%0A' +
        (d.obs ? '%0A*Situação:* ' + d.obs : '');
      window.dataLayer.push({event:'indicacao_enviada', tipo:d.tipo});
      /* Se houver backend, troque este trecho por um fetch para o seu endpoint. */
      window.open('https://wa.me/' + WA + '?text=' + msg, '_blank');
      frm.reset();
    });
  }

  /* ---------- CATÁLOGO DROPDOWN ---------- */
  var catBtn = document.getElementById('catalogo-toggle');
  var catMenu = document.getElementById('catalogo-menu');
  if (catBtn && catMenu) {
    catBtn.addEventListener('click', function(e){
      e.stopPropagation();
      var open = catMenu.style.display === 'block';
      catMenu.style.display = open ? 'none' : 'block';
      catBtn.setAttribute('aria-expanded', !open);
    });
    document.addEventListener('click', function(){
      catMenu.style.display = 'none';
      catBtn.setAttribute('aria-expanded', 'false');
    });
    catMenu.addEventListener('click', function(e){ e.stopPropagation(); });
  }

  /* ---------- EVENTOS GTM ---------- */
  document.querySelectorAll('[data-gtm]').forEach(function(el){
    el.addEventListener('click', function(){ window.dataLayer.push({event:'click_' + el.getAttribute('data-gtm')}); });
  });
})();
</script>

<?php get_footer(); ?>
